  // them, so they are listed with a † only. (\bH20\b leaves H200 alone.)
  [/\bH20\b/i, "H20"], [/RTX\s*5090/i, "RTX 5090"], [/RTX\s*4090/i, "RTX 4090"],
  [/RTX\s*PRO\s*6000/i, "RTX PRO 6000"], [/MI355X/i, "MI355X"], [/MI300X/i, "MI300X"]
